static const char *note_label_sym(C64 *c, int ir_id, int a64lab) {
    const char *fn = (c->fn && c->fn->name) ? c->fn->name : "fn";
    size_t n = runtime.strlen(fn) + 24;
    char *buf = xmalloc(n);
    runtime.snprintf(buf, n, ".L%s_%d", fn, ir_id);
    for (size_t i = 0; i < c->nlrel; i++) {
        if (runtime.strcmp(c->lrel[i].name, buf) == 0) {
            runtime.free(buf);
            return c->lrel[i].name;
        }
    }
    if (c->nlrel == c->caplrel) {
        c->caplrel = c->caplrel ? c->caplrel * 2 : 8;
        c->lrel = runtime.realloc(c->lrel, c->caplrel * sizeof *c->lrel);
        if (!c->lrel) { runtime.fprintf(runtime.stderr, "fakecc: OOM\n"); runtime.exit(1); }
    }
    c->lrel[c->nlrel].a64lab = a64lab;
    c->lrel[c->nlrel].name = buf;
    c->nlrel++;
    return buf;
}
