    runtime.memset(c->alloca_off, 0, (size_t)nv * sizeof(int));
    c->alloca_aln = xmalloc((size_t)nv * sizeof(int));
    runtime.memset(c->alloca_aln, 0, (size_t)nv * sizeof(int));
