            if (scalar_fp_val(c, s->dst)) {
                int p = load_ptrv(c, s->a, -1);
                int h = fp_home(c, s->dst);
                int d = h >= 0 ? h : A64_V31;
                if (vw(c, s->dst) == 8) a64_ldr_d(a, d, p, 0);
                else a64_ldr_s(a, d, p, 0);
                if (h < 0) commit_fp(c, s->dst, d);
                break;
            }
            int p = load_ptrv(c, s->a, -1);
