            if (buf == spv) spv = A64_X17;
            a64_ldr64(a, pc, buf, 8);
            a64_ldr64(a, spv, buf, 16);
            a64_ldr64(a, A64_FP, buf, 0);
            mov_sp_like(a, A64_SP, spv);
            a64_br_reg(a, pc);
