    a64_bind(a, epilog);
    mov_sp_like(a, A64_SP, A64_FP);
    for (int p = 0; p < ncs / 2; p++)
        a64_ldp64(a, cs[2*p], cs[2*p+1], A64_FP, 16 + 16*p, A64_PAIR_OFFSET);
